+const VS_POS = /* glsl */`vec4 crPos = vec4( position, 1.0 );
+vec3 transformed = vec3( dot( crR0, crPos ), dot( crR1, crPos ), dot( crR2, crPos ) );
+#ifdef USE_ALPHAHASH
