+  assert.equal(crowdRate(1.3, 0, 0.7), 1);
+  assert.ok(Math.abs(crowdRate(0.6, 1.0, 0.5) - 2 * crowdRate(0.6, 1.0, 1)) < 1e-12);   // 0,6 → 1,2: chưa chạm trần
